  "\uC57D\uC721\uAC15\uC2DD? \uC6C3\uAE30\uC9C0 \uB9C8\uC138\uC694.": (u, p) => immuneAllies(p, (a) => a.base.gender === "FEMALE" && gradeIdx(a) <= gradeIdx("HIGH RARE"), 2),
