  // 신아린
  "\uB354 \uC774\uC0C1\uC758 \uBE44\uADF9\uC740 \uC5C6\uC5B4!": (u, p) => immuneAllies(p, (a) => a.base.gender === "FEMALE" && gradeIdx(a) <= gradeIdx("HIGH RARE"), 2),
