  MANA_START: 40,
  MANA_PER_TURN: 20,
  MANA_MAX: 100,
  MAX_ABYSS_PER_DECK: 1,
  // 마나는 이월: 첫 턴 40, 이후 매 턴 +20(+가속기), 최대 100
  COUNTER_RATIO: 0.5,
