  MAX_TURNS: 40,
  // 전체 40턴(각자 20턴) 후 판정승
  MR_HERO_DMG_RATIO: 0.2,
  // MYTHIC RARE 카드가 진영(영웅)에 주는 피해 배율 (일반·스킬·초과 피해)
  SACRIFICE_RATIO: 0.5,
  // 희생: 필드 카드 1장 제거 → 코스트 × 0.5 마나 (턴당 1회)
  ACCEL_COST: 30,
  ACCEL_BONUS: 5,
  ACCEL_MAX: 5,
  // 마나 가속기: 다음 턴부터 매 턴 +5, 최대 5회
  // 덱 구성 (등급별 장수, 합계 30)
  DECK_COMPOSITION: { "NORMAL": 10, "RARE": 8, "HIGH RARE": 6, "SUPER RARE": 4, "ULTRA RARE": 2 },
  MYTHIC_CHANCE: 0.15,
  SECOND_PLAYER_BONUS_CARDS: 1,
  RECALL_COST_RATIO: 0.5,
  // 회수 비용 = ceil(코스트 × 비율)
  AI_RECALL_MIN_COST: 30,
  // AI가 회수를 고려하는 최소 코스트
  KILL_MANA_RATIO: 0.3,
  // 처치 시 즉시 마나 = round(처치 카드 코스트 × 0.3), 최대 마나까지
  // 레벨/경험치: XP: 처치(killXp) + 공격 + 턴 종료 생존. 다음 레벨 필요 XP = round(XP_BASE × 레벨^XP_EXP)
  LEVEL_MAX: 10,
  // Lv10 = 영웅 카드
  XP_BASE: 5.5,
  XP_EXP: 1.3,
  // Lv1→2: 6, Lv5→6: 45, Lv9→10: 96 (누적 약 430)
  KILL_XP_LEVEL_BONUS: 0.2,
  // 처치 XP = round(처치 카드 코스트 × (1 + 처치 카드 레벨 × 0.2))
  ATTACK_XP: 5,
  // 공격할 때마다 (살아남으면) 공격 카드 XP
  TURN_END_XP: 4,
  BLOCK_XP: 3,
  // 막기(반격 피해 > 0)마다 막은 카드 XP             // 내 턴 종료 시 필드에 살아있는 카드마다 XP
  LEVEL_UP_RATIO: 0.1,
  // Lv2~5: 레벨업마다 원본 ATK·HP의 +10%
  LEVEL_UP_RATIO_HIGH: 0.05,
  // Lv6~10: 원본의 +5% (체감)
  LEVEL_HIGH_FROM: 6,
  // 영웅 공격 제한
  HERO_GUARD_FIELD: 4,
  // 상대 필드가 이 장수 이상이면 영웅 공격 불가 (카드만 공격)
  HERO_LOCK_TURNS: 2,
  // 수비대장 흔들림: 한 번에 최대 HP의 이 비율 이상 맞으면 → STAGGER_TURNS 턴 ATK·DEF 감소, 받는 피해 일부가 진영 HP로
  STAGGER_HIT_PCT: 0.15,
  STAGGER_TURNS: 1,
  STAGGER_DOWN: 0.2,
  STAGGER_PASS: 0.5,
  STAGGER_CD: 2,
  // 자기 첫 N턴 동안은 영웅 공격·초과 피해 불가
